 p=dict(study='same_architecture_tree_unseen_generalization',version='1.0',arm=arm,status='APPROVED_DECISION_TREE_FULL_AND_FOREST_PILOT_ONLY',source_root=str(SOURCE),datasets=DATASETS,seeds=seeds,model_counts=counts,methods=methods,budgets=old['budgets'] if arm=='decision_tree' else {ds:[0,bs[0],bs[-1]] for ds,bs in full.items()},full_positive_budgets=full,rounds=100,eta='sqrt(log(m)/200)',loss='(1-p)^2',favorable_threshold=.5,trees_per_forest=10,max_depth=4,min_samples_leaf=5,max_features='sqrt',forest_bootstrap=True,forest_probability_aggregation=True,competing_candidate_limit=1536,unseen_candidate_limit=4096,reference_candidate_count=96,validation_allowance=.05,unseen_models_per_panel=50,panels=['refit','bootstrap'],unseen_primary='fresh fit seed; same saved training data',unseen_secondary='fresh outer training-row bootstrap and fit seed; same fixed validation cutoff',panel_selection='first 50 eligible unique fingerprints excluding competing models; no outcome/factual/test-performance filtering; no moving reference; reserve exhaustion is explicit failure',unseen_panel_overlap='each panel unique and disjoint from optimized models; cross-panel structural overlap is allowed and recorded by fingerprints',cohort='original saved 5-person prefix; forest pilot first person (index 0) per seed; no forest-specific reselection',absolute_deadline_epoch=None,full_forest_authorized=False,source_new_optimization=False,immutable=True,no_empirical_feature_boxes=True,coordinate_semantics='float32; standardized L2; continuous feature relaxation',orpm_call_seconds=1,baseline_call_seconds=30,threads=1,return_rule='best observed worst-loss action including factual, L2 tie break',same_source_solver_parameters=True,postsolve_ORPM_witnesses='audit certificates only; never change baseline returned action',numerical_safeguards='raw statuses retained; full encoded witness audit before rejecting contradictions; exact rational distance proofs for rejected budget-infeasible leaf incumbents; no retries',reference_definition='saved SingleTreeReference is best reachable probability with L2 tie-break, factual if accepted; SingleForestReference is minimum cost for p>=.5, factual if already accepted; unresolved native reference yields labeled failed factual action',inference='people averaged within seed then equal seed weights; pointwise t intervals, ten-seed df9 for DT and two-seed df1 for pilot; report conditional-subset support; no pooling budgets/counts/datasets',analysis_metrics=['seen_joint','unseen_mean','unseen_joint','seen_to_unseen_joint_drop','factual_acceptance','acceptance_gain','unseen_panel_size_5_10_25_50'],run_full_after_pilot=False,authorization='User approved decision-tree unseen evaluation and random-forest pilot; estimate full forest using measured pilot timings BEFORE any full launch. Hourly progress and ETA updates.',runtime_planning_hours=[.5,2] if arm=='decision_tree' else [1,4])
